 [Theory][InlineData(true)][InlineData(false)]public async Task Settlement_concurrency_cannot_spend_same_balance_twice(bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var f=api.Authenticated(x.Approver);await ApproveRun(f,await Run(c,x));var input=new IncentiveSettlementInput(await Claim(),30,0,await Today(),Code(),"Transfer","Reviewed",E(Array.Empty<object>()));var key=Code();var results=await Task.WhenAll(Send(c,HttpMethod.Post,"/incentives/settlements",input,key:key),Send(c,HttpMethod.Post,"/incentives/settlements",input with{Reference=sameKey?input.Reference:Code()},key:sameKey?key:Code()));Assert.Equal(sameKey?2:1,results.Count(r=>r.StatusCode==HttpStatusCode.Created));Assert.Equal(1L,await S("SELECT count(*)FROM incentives.settlements WHERE company_id=@c",("c",db.Company)));Assert.Equal(0,await Balance(await Claim()));}
 [Fact]public async Task Audit_failure_rolls_back_accrual_and_retry_keeps_single_financial_effect()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var f=api.Authenticated(x.Approver);var r=await Run(c,x);var key=Code();await S($"CREATE FUNCTION incentives.test_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='incentives.changed'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER c08_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION incentives.test_fail()");try{await Expect(await Send(f,HttpMethod.Post,$"/incentives/runs/{Id(r)}/approve",version:1,key:key),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM incentives.accruals WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER c08_fail ON platform.audit_events;DROP FUNCTION incentives.test_fail()");}await ApproveRun(f,r,key);Assert.Equal(30,await Balance(await Claim()));}
