 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var f=api.Authenticated(x.Approver);await ApproveRun(f,await Run(c,x));await Expect(await Send(c,HttpMethod.Post,"/incentives/settlements",new IncentiveSettlementInput(await Claim(),30,0,await Today(),Code(),"Clearing","Payroll reference",E(Array.Empty<object>()))),HttpStatusCode.Created);var first=await Get(c,"/incentives/ledger?pageSize=1");var next=await Get(c,"/incentives/ledger?page=2&pageSize=1");Assert.Equal(1,first.GetProperty("claimCount").GetInt32());Assert.Equal(1,first.GetProperty("settlementCount").GetInt32());Assert.Single(first.GetProperty("claims").EnumerateArray());Assert.Empty(next.GetProperty("claims").EnumerateArray());Assert.Empty(next.GetProperty("settlements").EnumerateArray());var own=(await Get(c,"/incentives/me"))[0];Assert.Equal("CLEARED",own.GetProperty("state").GetString());Assert.Equal(30,D(own.GetProperty("transferredNet")));Assert.DoesNotContain("PAID",own.GetRawText(),StringComparison.OrdinalIgnoreCase);}

